# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def boundaryOfBinaryTree(self, root: TreeNode):
        if not root:
            return []

        # Utility to check if a node is a leaf
        def is_leaf(node):
            return node.left is None and node.right is None

        # Add left boundary (excluding leaves)
        def add_left_boundary(node, res):
            curr = node.left
            while curr:
                if not is_leaf(curr):
                    res.append(curr.val)
                if curr.left:
                    curr = curr.left
                else:
                    curr = curr.right

        # Add all leaves (in L->R order)
        def add_leaves(node, res):
            if node is None:
                return
            if is_leaf(node):
                res.append(node.val)
            else:
                add_leaves(node.left, res)
                add_leaves(node.right, res)

        # Add right boundary (excluding leaves), reversed at the end
        def add_right_boundary(node, res):
            curr = node.right
            stack = []
            while curr:
                if not is_leaf(curr):
                    stack.append(curr.val)
                if curr.right:
                    curr = curr.right
                else:
                    curr = curr.left
            while stack:
                res.append(stack.pop())

        boundary = []
        if not is_leaf(root):
            boundary.append(root.val)

        add_left_boundary(root, boundary)
        add_leaves(root, boundary)
        add_right_boundary(root, boundary)

        return boundary
